export { vbaStart, allModules, makeHost };
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const KW = ['And', 'As', 'Boolean', 'ByRef', 'Byte', 'ByVal', 'Call', 'Case', 'Const', 'Currency', 'Date', 'Debug', 'Dim', 'Do', 'Double', 'Each', 'Else', 'ElseIf', 'Empty', 'End', 'Erase', 'Error', 'Exit', 'Explicit', 'False', 'For', 'Function', 'GoTo', 'If', 'In', 'Integer', 'Is', 'Let', 'Like', 'Long', 'LongLong', 'Loop', 'Me', 'Mod', 'New', 'Next', 'Not', 'Nothing', 'Null', 'Object', 'On', 'Option', 'Optional', 'Or', 'ParamArray', 'Preserve', 'Print', 'Private', 'Public', 'ReDim', 'Resume', 'Select', 'Set', 'Single', 'Static', 'Step', 'Stop', 'String', 'Sub', 'Then', 'To', 'True', 'Until', 'Variant', 'Wend', 'While', 'With', 'Xor', 'Compare', 'Base', 'Text', 'Binary', 'Global', 'Rem'];
const KWMAP = Object.fromEntries(KW.map(k => [k.toLowerCase(), k]));
