  outboxHTML() { const o = (this.xh && this.xh.outbox) || []; if (!o.length) return ''; return `<div class="vf-d">📨 Outlook</div>${o.map((m, k) => `<div class="vf-f made" data-mail="${k}" data-z="vmail:${k + 1}">${m.how === 'send' ? '📤' : '✉️'} ${esc(m.subject || '(no subject)')} <small>to ${esc(m.to || m.cc || '?')}${m.attachments.length ? ' · 📎 ' + esc(m.attachments.join(', ')) : ''} · ${m.how === 'send' ? 'in the Outbox' : m.how === 'display' ? 'opened with .Display' : 'draft'}</small></div>`).join('')}`; }
