    const icon = k => ({ xlsx: '🟩', xlsm: '🟩', xlam: '🧩', csv: '📄', pdf: '📕', txt: '📄', folder: '📁' }[k] || '📄');
    const me = (this.v.path || 'C:\\Users\\you\\Documents') + '\\' + (this.v.book || 'Book1.xlsm');
