function removeProc(code, name) { const lines = String(code).split('\n'); const out = []; let skip = false; for (const l of lines) { if (!skip && new RegExp(`^\\s*(public\\s+|private\\s+)?sub\\s+${name}\\b`, 'i').test(l)) { skip = true; continue; } if (skip) { if (/^\s*end\s+sub\b/i.test(l)) skip = false; continue; } out.push(l); } return out.join('\n').replace(/\n{3,}/g, '\n\n'); }
